// TASK-0035 — Context Panel, Direct Children & Safe Copy, product acceptance
// in real WebView2. No simulated DOM, no alternate renderer, no personal
// data: the tree under test was generated by task0035-seed-proof.py and
// dies with the proof root.
//
// Unlike TASK-0034's single-launch replay, `TASK-0035` A requires the
// details-panel preference to survive a REAL process exit and restart — not
// something a page can fake from inside itself. This script is therefore
// invoked THREE times by task0035-webview2.ps1, once per real launch, with
// a `phase` argument (1, 2 or 3) selecting what that launch proves. Each
// phase writes its own partial result under the proof root; the `.ps1`
// merges all three (plus its own OS-level clipboard check, done outside
// this script entirely — see below) into the one published artifact.
//
// Reuses TASK-0033/0034's harness technique (REAL_ROOT registered directly
// into a fresh sandbox catalogue, then the real product driven through CDP)
// rather than building a second framework.
import assert from "node:assert/strict";
import { writeFile, readFile } from "node:fs/promises";
import { setTimeout as pause } from "node:timers/promises";
import { join } from "node:path";

const port = Number(process.argv[2]);
const variant = process.argv[3];
const phase = Number(process.argv[4]);
assert(/^task0035-[a-f0-9]+$/.test(variant));
assert([1, 2, 3].includes(phase), `phase must be 1, 2 or 3: ${phase}`);

const seed = JSON.parse(
  (
    await new Promise((resolve, reject) => {
      let text = "";
      process.stdin.setEncoding("utf8");
      process.stdin.on("data", (c) => (text += c));
      process.stdin.on("end", () => resolve(text));
      process.stdin.on("error", reject);
    })
  ).replace(/^﻿/, ""), // PowerShell's pipe prepends a UTF-8 BOM.
);
const { brainId, absolutePath, needleName, needleRelativePath, cRelativePath, cDirectChildCount } = seed;

let target;
for (let n = 0; n < 100; n++) {
  try {
    const pages = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
    target = pages.find((p) => p.type === "page");
    if (target) break;
  } catch {}
  await pause(200);
}
assert(target, "WebView2 CDP page unavailable");
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => {
  ws.addEventListener("open", resolve, { once: true });
  ws.addEventListener("error", reject, { once: true });
});
let serial = 0;
const pending = new Map();
const fatal = [];
ws.addEventListener("message", ({ data }) => {
  const event = JSON.parse(data);
  if (event.id) {
    const p = pending.get(event.id);
    pending.delete(event.id);
    if (event.error) p?.reject(new Error(JSON.stringify(event.error)));
    else p?.resolve(event.result);
  } else if (
    event.method === "Runtime.exceptionThrown" ||
    (event.method === "Log.entryAdded" && event.params.entry.level === "error")
  ) {
    fatal.push(event);
  }
});
const send = (method, params = {}) =>
  new Promise((resolve, reject) => {
    const id = ++serial;
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify({ id, method, params }));
  });
async function evaluate(expression) {
  const r = await send("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true });
  if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description ?? r.exceptionDetails.text);
  return r.result.value;
}
async function until(expression, limit = 240000) {
  const start = Date.now();
  while (Date.now() - start < limit) {
    if (await evaluate(expression)) return;
    await pause(100);
  }
  throw new Error(`timeout: ${expression}`);
}
const invoke = (command, args = {}) =>
  evaluate(`window.__TAURI_INTERNALS__.invoke(${JSON.stringify(command)},${JSON.stringify(args)})`);
await send("Runtime.enable");
await send("Log.enable");
await send("Page.enable");

async function key(k) {
  const vk = k === "Enter" ? 13 : 0;
  await send("Input.dispatchKeyEvent", {
    type: "keyDown",
    key: k,
    code: k,
    windowsVirtualKeyCode: vk,
    nativeVirtualKeyCode: vk,
    ...(k === "Enter" ? { text: "\r", unmodifiedText: "\r" } : {}),
  });
  await send("Input.dispatchKeyEvent", { type: "keyUp", key: k, code: k, windowsVirtualKeyCode: vk, nativeVirtualKeyCode: vk });
  await pause(120);
}
async function activate(selector) {
  const found = await evaluate(`!!document.querySelector(${JSON.stringify(selector)})`);
  assert(found, `activate: selector not found — ${selector}`);
  await evaluate(`document.querySelector(${JSON.stringify(selector)}).focus()`);
  await key("Enter");
}
const jargon = ["view_budget_or_focus", "outside_current_projection", "omitted_direct_children", "enfants directs hors vue"];
function assertNoJargon(text, where) {
  for (const word of jargon) assert(!text.includes(word), `internal jargon "${word}" leaked into ${where}`);
}
const escaped = absolutePath.split("\\").join("\\\\");
function assertNoPathLeak(text, where) {
  assert(!text.includes(absolutePath) && !text.includes(escaped), `absolute path leaked into ${where}`);
}
async function assertPanelVisible(expected, where) {
  const present = await evaluate(`!!document.querySelector('[aria-label="Détails de la sélection"]')`);
  assert.equal(present, expected, `details panel visibility at ${where}: expected ${expected}, found ${present}`);
}
async function waitForAppReady() {
  await until(`!!document.querySelector('[data-testid="details-panel-toggle"]')`);
  await until(`document.querySelector('[data-testid="lifecycle-open"]') && !document.querySelector('[data-testid="lifecycle-open"]').disabled`);
}

const results = {};
const proofRoot = join(".filetopo-sandbox", variant);

// ---------------------------------------------------------------------------
if (phase === 1) {
  // --- index the large synthetic REAL_ROOT tree, by a real keystroke -------
  await waitForAppReady();
  await activate('[data-testid="lifecycle-refresh"]');
  await until(`!document.querySelector('[data-testid="lifecycle-open"]').disabled && document.querySelectorAll('[role="treeitem"]').length > 0`);
  const build = await invoke("map_view", { brainId });
  assert(build.nodeCount >= 5000, `indexed corpus too small: ${build.nodeCount}`);
  results.indexedNodeCount = build.nodeCount;

  // --- A. the panel is visible on a fresh profile, no preference written yet
  await assertPanelVisible(true, "fresh profile, before any preference is written");
  const toggleLabelDefault = await evaluate(`document.querySelector('[data-testid="details-panel-toggle"]').textContent`);
  assert.equal(toggleLabelDefault, "Masquer les détails", "the toggle names the action available, not the current state");
  results.panelVisibleByDefault = true;

  // --- B. select the C folder (a top-level directory, well inside the
  // ordinary 64-block projection) and page through its direct children ------
  const cRef = await invoke("map_resolve_node", { brainId, relativePath: cRelativePath });
  assert(cRef, "C must resolve in the freshly built index");
  // The root is auto-selected on boot (`booted` effect in `MapApp.tsx`),
  // and its own dedicated children page already lists A/B/C/D and the loose
  // root files (9 direct children, one page) — a real keystroke on C's own
  // row selects it via the ordinary navigation `onSelect` already reuses,
  // with no SVG-coordinate click needed.
  await until(`document.querySelector('[data-testid="children-total"]')?.getAttribute('data-total') !== null`);
  await activate(`[data-testid="child-node"][data-node-id="${cRef.nodeId}"]`);
  await until(`document.querySelector('.details__name')?.textContent?.trim() === "C"`);

  const domTotalFirst = await evaluate(`document.querySelector('[data-testid="children-total"]')?.getAttribute('data-total')`);
  assert.equal(Number(domTotalFirst), cDirectChildCount, "the DOM must show C's exact direct-child count");
  const domLimit = await evaluate(`document.querySelector('[data-testid="children-total"]')?.getAttribute('data-limit')`);
  assert.equal(domLimit, "50", "a children page is bounded to the product ceiling");
  const firstPageCount = await evaluate(`document.querySelectorAll('[data-testid="child-node"]').length`);
  assert.equal(firstPageCount, 50, "the first page must hold exactly 50 rows");

  // Cross-check against a direct call to the same command the UI itself calls.
  const directPage = await invoke("map_node_children", { reference: cRef, after: null, limit: 50 });
  assert.equal(directPage.total, cDirectChildCount);
  assert.equal(directPage.items.length, 50);
  assert.equal(directPage.parentNodeId, cRef.nodeId);
  results.childrenPagination = {
    total: directPage.total,
    boundedToProductLimit: directPage.limit <= 50,
  };

  // The needle sorts first among C's children (`c` < `e`, and C holds no
  // subdirectories to sort ahead of it) — page 1's first row.
  const firstPageIds = await evaluate(
    `[...document.querySelectorAll('[data-testid="child-node"]')].map(b => b.getAttribute('data-node-id'))`,
  );
  const needleButtonName = await evaluate(
    `document.querySelector('[data-testid="child-node"]')?.textContent ?? ''`,
  );
  assert(needleButtonName.includes(needleName), `page 1's first row must be the needle: ${needleButtonName}`);

  // --- page suivante / précédente, real keystrokes, no duplication or loss -
  await activate('[data-testid="children-next"]');
  await until(
    `document.querySelector('[data-testid="child-node"]')?.getAttribute('data-node-id') !== ${JSON.stringify(firstPageIds[0])}`,
  );
  const secondPageIds = await evaluate(
    `[...document.querySelectorAll('[data-testid="child-node"]')].map(b => b.getAttribute('data-node-id'))`,
  );
  assert.equal(secondPageIds.length, 50, "page 2 must also hold 50 rows — 100 < total");
  const overlap = firstPageIds.filter((id) => secondPageIds.includes(id));
  assert.equal(overlap.length, 0, "page 2 must not repeat a row from page 1");
  results.pageForwardNoOverlap = true;

  await activate('[data-testid="children-previous"]');
  await until(
    `document.querySelector('[data-testid="child-node"]')?.getAttribute('data-node-id') === ${JSON.stringify(firstPageIds[0])}`,
  );
  const backToFirstIds = await evaluate(
    `[...document.querySelectorAll('[data-testid="child-node"]')].map(b => b.getAttribute('data-node-id'))`,
  );
  assert.deepEqual(backToFirstIds, firstPageIds, "page précédente must restore the exact original page 1");
  results.pageBackwardExactRestore = true;

  // --- C. select the needle child (outside the ordinary map projection —
  // only `C` itself, not its file children, is a materialised card) ---------
  await activate('[data-testid="child-node"]'); // page 1's first row, the needle
  await until(`document.querySelector('.details__name')?.textContent?.trim() === ${JSON.stringify(needleName)}`);
  const focusedPath = await evaluate(`document.querySelector('.details__path')?.textContent?.trim()`);
  assert.equal(focusedPath, needleRelativePath, "the details panel must show the activated child");
  const activeDescendant = await evaluate(`document.querySelector('[data-testid="composed-canvas"]')?.getAttribute('aria-activedescendant')`);
  assert(activeDescendant?.endsWith(`-map-node-${directPage.items[0].nodeId}`), "the map's selected card must be the activated child");
  results.childOutsideProjectionSyncsMapAndDetails = true;

  // --- D. Ouvrir dans l'Explorateur, on a synthetic target only ------------
  // Direct invoke, exactly as TASK-0034's replay does — avoids a second
  // visible Explorer window for the same fact; the button's own wiring is
  // proven by DetailsPanel.test.tsx.
  const revealReference = { brainId, nodeId: directPage.items[0].nodeId };
  await invoke("map_reveal_node", { reference: revealReference });
  results.revealSpawnSucceeded = true;

  // --- E. Copier le chemin, through a real keystroke on the actual button --
  // Safe to activate for real here (unlike reveal): writing to the
  // clipboard spawns no window. The OS-level clipboard content is read and
  // compared by task0035-webview2.ps1 itself, in the very same session —
  // never by this script, and never printed by either: the artefact keeps
  // only `match: true/false`, per `TASK-0035` D.
  await activate('[data-testid="copy-path"]');
  await pause(300);
  const copyErrorShown = await evaluate(`!!document.querySelector('[data-testid="copy-error"]')`);
  assert.equal(copyErrorShown, false, "Copier le chemin must not have failed");
  results.copyClickSucceeded = true;

  // --- F. no absolute path or internal jargon anywhere visible -------------
  const bodyText = await evaluate("document.body.textContent");
  assertNoJargon(bodyText, "page body text");
  assertNoPathLeak(bodyText, "page body text");
  for (const payload of [build, directPage]) {
    assertNoPathLeak(JSON.stringify(payload), "invoke payload");
  }

  // --- G. masquer, by a real keystroke — persisted for phase 2 to find -----
  await activate('[data-testid="details-panel-toggle"]');
  await assertPanelVisible(false, "immediately after Masquer les détails");
  results.hiddenAfterToggle = true;

  await writeFile(join(proofRoot, "phase1.json"), JSON.stringify(results));
  console.log(JSON.stringify({ phase, ok: true }));
}

// ---------------------------------------------------------------------------
if (phase === 2) {
  await waitForAppReady();
  // The index already exists from phase 1 — map_open reuses it, no
  // "Indexer" keystroke needed this time.
  await until(`document.querySelectorAll('[role="treeitem"]').length > 0`);

  await assertPanelVisible(false, "after a real restart, following Masquer in phase 1");
  const toggleLabelHidden = await evaluate(`document.querySelector('[data-testid="details-panel-toggle"]').textContent`);
  assert.equal(toggleLabelHidden, "Afficher les détails", "the toggle now names the opposite action");
  results.stillHiddenAfterRestart = true;

  // --- réafficher, by a real keystroke — persisted for phase 3 to find -----
  await activate('[data-testid="details-panel-toggle"]');
  await assertPanelVisible(true, "immediately after Afficher les détails");
  results.visibleAfterToggle = true;

  const bodyText = await evaluate("document.body.textContent");
  assertNoJargon(bodyText, "page body text");
  assertNoPathLeak(bodyText, "page body text");

  await writeFile(join(proofRoot, "phase2.json"), JSON.stringify(results));
  console.log(JSON.stringify({ phase, ok: true }));
}

// ---------------------------------------------------------------------------
if (phase === 3) {
  await waitForAppReady();
  await until(`document.querySelectorAll('[role="treeitem"]').length > 0`);

  await assertPanelVisible(true, "after a second real restart, following Afficher in phase 2");
  const toggleLabelVisible = await evaluate(`document.querySelector('[data-testid="details-panel-toggle"]').textContent`);
  assert.equal(toggleLabelVisible, "Masquer les détails", "the toggle names Masquer again, now that the panel is visible");
  results.stillVisibleAfterSecondRestart = true;

  const bodyText = await evaluate("document.body.textContent");
  assertNoJargon(bodyText, "page body text");
  assertNoPathLeak(bodyText, "page body text");

  const hostLog = await readFile(join(proofRoot, "app.log"), "utf8").catch(() => "");
  assertNoPathLeak(hostLog, "host log");
  assertNoJargon(hostLog, "host log");

  const screenshot = await send("Page.captureScreenshot", { format: "png" });
  await writeFile(join(proofRoot, "context-panel.png"), Buffer.from(screenshot.data, "base64"));

  await writeFile(join(proofRoot, "phase3.json"), JSON.stringify(results));
  console.log(JSON.stringify({ phase, ok: true }));
}

assert.equal(fatal.length, 0, `fatal page/console errors in phase ${phase}`);
await writeFile(join(proofRoot, `phase${phase}-fatal-count.json`), JSON.stringify(fatal.length));
ws.close();
